        console.log(`[pick] cleared selection on "${layerId}"`);
      } else {
        console.log(`[pick] selected ${selectedIds.length} feature(s) on "${layerId}":`, selectedIds);
      }
    }
  );
  console.log("Picking enabled on all layers");

  // ── 14. Start rendering ────────────────────────────────────────────────────
  map.draw();
  hideLoading();
  setPhase("Done");
  console.log("=== Application ready ===");
}

